18		"strings"
19		"time"
20	
21		"github.com/spf13/cobra"
22	)
23	
24	// Regression Radar: turn the brain from a passive librarian into an active reviewer.
25	// Given a query (task description + failing identifiers) it compares the CURRENT working
26	// tree against what the session history asserts the code looked like, and flags two narrow,
27	// high-precision shapes of regression:
28	//
29	//	changed: history asserts `<id> + "<literal>"` (or a `..` range) at a locus, but the
30	//	         current tree keeps the distinctive operand while the identifier was swapped out
31	//	         (e.g. scopeBaseRef+"..HEAD"  ->  "master..HEAD").
32	//	deleted: history asserts an assignment whose target contains <id> (e.g.
33	//	         `state.TranscriptPath = resolved`) and that assignment is now absent EVERYWHERE in
34	//	         the candidate locus/file, though the identifier still lives in the tree.
35	//
36	// It reads RAW sessions (inspectBrainRawText), not the index, because the indexed Summary
37	// collapses code to prose; the precise invariant survives only in raw text. History file hints
38	// keep multi-locus checks local, so an intact peer file/site cannot mask a nearby regressed site.
39	// Unhinted fallbacks stay conservative and global to avoid noisy deletion claims.
40	
41	const (
42		regressionMaxFileBytes = 1 << 20
43		regressionMaxAnomalies = 50
44	)
45	
46	type regressionAnomaly struct {
47		File             string   `json:"file"`
48		Line             int      `json:"line,omitempty"`
49		Kind             string   `json:"kind"` // "changed" | "deleted"
50		Current          string   `json:"current"`
51		Expected         string   `json:"expected"`
52		Identifier       string   `json:"identifier"`
53		Symbol           string   `json:"symbol,omitempty"`
54		RelatedLocations []string `json:"related_locations,omitempty"`
55		Confidence       float64  `json:"confidence"`
56		Reason           string   `json:"reason"`
57		Evidence         string   `json:"evidence"`
58		rankBoost        int
59	}
60	
61	type regressionReport struct {
62		SchemaVersion int                 `json:"schema_version"` // shares reviewReportSchemaVersion; see docs/diffless_review_seam.md
63		GeneratedAt   time.Time           `json:"generated_at"`
64		Query         string              `json:"query"`
65		RepoPath      string              `json:"repo_path"`
66		BrainPath     string              `json:"brain_path"`
67		Anomalies     []regressionAnomaly `json:"anomalies"`
68		Scanned       int                 `json:"scanned_files"`
69		// HistoryTruncated reports that the raw-history walk stopped at a hard cap before the end of
70		// the brain. When it is true, an empty Anomalies list means "nothing found in the part that
71		// was read", never "nothing exists".
72		HistoryTruncated bool     `json:"history_truncated,omitempty"`
73		Warnings         []string `json:"warnings,omitempty"`
74	}
75	
76	type regressionDetectorOptions struct {
77		limit            int
78		json             bool
79		includeDeletions bool // deletions are higher-recall but noisier (no recency data); opt-in
80		locationOnly     bool // emit file:line only, NOT expected/current — so a fair A/B can't paste the answer
81		patterns         bool // opt-in: attach V2 risk/practice/task corpus context for the finding files
82	}
83	
84	type changeSignal struct {
85		id      string   // lowercased identifier
86		operand string   // distinctive operand, lowercased+despaced (e.g. `..head`)
87		raw     string   // human-readable asserted expression
88		ev      string   // session path:line
89		hints   []string // code files named on the same history line as the asserted invariant
90	}
91	
92	type deleteSignal struct {
93		id      string
94		target  string // normalized LHS/callee + operator (e.g. `state.transcriptpath=` or `state.realign(`)
95		rhs     string // despaced right-hand side / first argument token — used to locate the home file
96		raw     string
97		ev      string
98		hints   []string // code files named on the same history line as the asserted invariant
99		anchors []string // peer assignments from the same history line, used to localize missing calls
100	}
101	
102	type candFile struct {
103		clean        string
104		lines        []string
105		norm         []string
106		semantic     bool // surfaced by the semantic index (a primary locus), not just named in a session
107		rank         int  // semantic rank (lower = stronger locus)
108		runtimeTrace bool // surfaced by a query-matching runtime trace edge
109		traceRank    int  // runtime trace rank (lower = stronger locus)
110		isTest       bool
111	}
112	
113	func regressionIsComment(line string) bool {
114		t := strings.TrimSpace(line)
115		return strings.HasPrefix(t, "//") || strings.HasPrefix(t, "*") || strings.HasPrefix(t, "/*") ||
116			strings.HasPrefix(t, "#") || strings.HasPrefix(t, "<!--")
117	}
118	
119	func regressionIsTestPath(p string) bool {
120		l := strings.ToLower(p)
121		return strings.Contains(l, "_test.") || strings.Contains(l, ".test.") || strings.Contains(l, ".spec.") ||
122			strings.Contains(l, "/test/") || strings.Contains(l, "/tests/") || strings.Contains(l, "/testdata/")
123	}
124	
125	var regressionCodeFilePattern = regexp.MustCompile(`[\w./-]+\.(?:go|ts|tsx|js|jsx|py|rs|java|kt|swift|c|cc|cpp|h|hpp)`)
126	
127	func regressionCleanRelPath(path string) string {
128		path = strings.ReplaceAll(path, "\\", "/")
129		return filepath.ToSlash(filepath.Clean(path))
130	}
131	
132	func regressionDespace(s string) string {
133		var b strings.Builder
134		for _, r := range s {
135			if r == ' ' || r == '\t' {
136				continue
137			}
138			b.WriteRune(r)
139		}
140		return strings.ToLower(b.String())
141	}
142	
143	func regressionLineFileHints(line string) []string {
144		seen := map[string]struct{}{}
145		var out []string
146		for _, fn := range regressionCodeFilePattern.FindAllString(line, -1) {
147			clean := regressionCleanRelPath(strings.TrimLeft(fn, "+-/ "))
148			if clean == "." || filepath.IsAbs(clean) || strings.HasPrefix(clean, "..") {
149				continue
150			}
151			if _, ok := seen[clean]; ok {
152				continue
153			}
154			seen[clean] = struct{}{}
155			out = append(out, clean)
156		}
157		return out
158	}
159	
160	func mergeRegressionHints(a, b []string) []string {
161		if len(b) == 0 {
162			return a
163		}
164		seen := map[string]struct{}{}
165		out := make([]string, 0, len(a)+len(b))
166		for _, h := range a {
167			if h == "" {
168				continue
169			}
170			seen[h] = struct{}{}
171			out = append(out, h)
172		}
173		for _, h := range b {
174			if h == "" {
175				continue
176			}
177			if _, ok := seen[h]; ok {
178				continue
179			}
180			seen[h] = struct{}{}
181			out = append(out, h)
182		}
183		return out
184	}
185	
186	// regressionExtractSignals pulls change + delete signals for one identifier from a (space-
187	// collapsed) history excerpt using identifier-anchored regexes — tight enough that line-number
188	// noise and common tokens don't leak in.
189	func regressionExtractSignals(id, excerpt, ev string) ([]changeSignal, []deleteSignal) {
190		q := regexp.QuoteMeta(id)
191		// Known recall limits (documented, not silently dropped): literals >80 chars are skipped, an
192		// all-lowercase identifier is never extracted as a query id upstream, and a literal that embeds
193		// the id (e.g. `foo+"foobar"`) won't match. These bound recall, not precision.
194		changeRe := regexp.MustCompile(`(?i)` + q + `\s*\+?\s*(?:"([^"]{2,80})"|([A-Za-z0-9_]*\.\.[A-Za-z0-9_]+))`)
195		assignRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]+)\s*(:?=)\s*([A-Za-z0-9_."'\[\]()+\-* ]{1,48})`)
196		callRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]*` + q + `[A-Za-z0-9_]*)\s*\(\s*([A-Za-z0-9_."'\[\]+\-* ]{1,48})\s*\)`)
197	
198		var changes []changeSignal
199		seenC := map[string]struct{}{}
200		for _, m := range changeRe.FindAllStringSubmatch(excerpt, -1) {
201			operand := m[1]
202			if operand == "" {
203				operand = m[2]
204			}
205			operand = regressionDespace(operand)
206			if len(operand) < 4 {
207				continue
208			}
209			if _, ok := seenC[operand]; ok {
210				continue
211			}
212			seenC[operand] = struct{}{}
213			changes = append(changes, changeSignal{id: id, operand: operand, raw: strings.TrimSpace(m[0]), ev: ev})
214		}
215	
216		var deletes []deleteSignal
217		seenD := map[string]struct{}{}
218		var peerAssignments []deleteSignal
219		for _, m := range assignRe.FindAllStringSubmatch(excerpt, -1) {
220			lhs := regressionDespace(m[1])
221			op := m[2]
222			// Only field/state assignments (`a.b = c`) are persistent invariants whose absence is a
223			// regression; `:=` locals are ephemeral, so their absence from a file is meaningless.
224			if op != "=" || !strings.Contains(lhs, ".") {
225				continue
226			}
227			target := lhs + op
228			rhsTok := regressionSignalHead(m[3])
229			if rhsTok == "" {
230				continue
231			}
232			peerAssignments = append(peerAssignments, deleteSignal{target: target, rhs: rhsTok})
233			if !strings.Contains(lhs, id) {
234				continue
235			}
236			k := target + "|" + rhsTok
237			if _, ok := seenD[k]; ok {
238				continue
239			}
240			seenD[k] = struct{}{}
241			raw := strings.TrimSpace(m[1]) + " " + op + " " + rhsTok
242			deletes = append(deletes, deleteSignal{id: id, target: target, rhs: rhsTok, raw: raw, ev: ev})
243		}
244		for _, m := range callRe.FindAllStringSubmatch(excerpt, -1) {
245			callee := regressionDespace(m[1])
246			if !strings.Contains(callee, id) || !strings.Contains(callee, ".") {
247				continue
248			}
249			argTok := regressionSignalHead(m[2])
250			if argTok == "" {
251				continue
252			}
253			target := callee + "("
254			k := target + "|" + argTok
255			if _, ok := seenD[k]; ok {
256				continue
257			}
258			seenD[k] = struct{}{}
259			var anchors []string
260			for _, p := range peerAssignments {
261				if p.rhs == argTok && p.target != target {
262					anchors = append(anchors, p.target)
263				}
264			}
265			raw := strings.TrimSpace(m[1]) + "(" + argTok + ")"
266			deletes = append(deletes, deleteSignal{id: id, target: target, rhs: argTok, raw: raw, ev: ev, anchors: anchors})
267		}
268		return changes, deletes
269	}
270	
271	func regressionSignalHead(raw string) string {
272		token := strings.TrimSpace(raw)
273		token = strings.TrimLeft(token, "\"'`([{")
274		token = strings.TrimRight(token, "\"'`)]},;")
275		for i := 0; i < len(token); i++ {
276			c := token[i]
277			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
278				continue
279			}
280			token = token[:i]
281			break
282		}
283		return strings.ToLower(token)
284	}
