286	// regressionScanCaps records whether a hard limit stopped the raw-history walk before it reached
287	// the end of the brain. A fired cap makes the scan PARTIAL: from that point on, the absence of a
288	// signal is no longer evidence that no such signal exists, so every caller must say so rather than
289	// print a clean bill of health.
290	type regressionScanCaps struct {
291		// FileCap is true when the walk hit maxFiles opened history files.
292		FileCap bool
293		// SignalCap is true when both the distinct-change and distinct-delete signal caps filled.
294		SignalCap bool
295		// Scanned is the number of history files actually opened before the walk ended.
296		Scanned int
297		// MaxFiles / MaxSignals are the limits in force, reported so the warning is self-explaining.
298		MaxFiles   int
299		MaxSignals int
300	}
301	
302	// Truncated reports whether the walk ended early, i.e. whether the scan is partial.
303	func (c regressionScanCaps) Truncated() bool { return c.FileCap || c.SignalCap }
304	
305	// Warning renders the one line a reader needs to know the scan was partial. Empty when it was not.
306	func (c regressionScanCaps) Warning() string {
307		switch {
308		case c.FileCap && c.SignalCap:
309			return fmt.Sprintf("history scan stopped early: hit both the %d-file cap and the %d-distinct-signal cap; results are partial and absence of a finding is not evidence of absence", c.MaxFiles, c.MaxSignals)
310		case c.FileCap:
311			return fmt.Sprintf("history scan stopped early: hit the %d-file cap after %d files; results are partial and absence of a finding is not evidence of absence", c.MaxFiles, c.Scanned)
312		case c.SignalCap:
313			return fmt.Sprintf("history scan stopped early: hit the %d-distinct-signal cap after %d files; results are partial and absence of a finding is not evidence of absence", c.MaxSignals, c.Scanned)
314		default:
315			return ""
316		}
317	}
318	
319	// regressionScanHistory is the capped walk without the truncation report, kept for callers that
320	// only need the signals. Prefer regressionScanHistoryCapped: a dropped cap report is exactly the
321	// silent failure this file's warnings exist to prevent.
322	func regressionScanHistory(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}, error) {
323		changes, deletes, files, _, err := regressionScanHistoryCapped(brainDir, ids)
324		return changes, deletes, files, err
325	}
326	
327	// regressionScanHistoryCapped walks the raw brain (sessions + exports) once and extracts
328	// change/delete signals for the given identifiers from every matching line of every file it
329	// reaches, so rare but precise invariants are not lost behind a top-N ranking.
330	//
331	// It is NOT unbounded, and the bound is not cosmetic: the walk stops outright (filepath.SkipAll)
332	// once it has opened maxFiles history files, or once it holds maxSignalsEach distinct change
333	// signals AND maxSignalsEach distinct delete signals. Whatever lies beyond that point in the walk
334	// is never read. The returned regressionScanCaps says whether that happened; callers must surface
335	// it, because "no signal found" and "stopped looking" are different answers.
336	func regressionScanHistoryCapped(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}, regressionScanCaps, error) {
337		const (
338			maxFiles       = 20000
339			maxLineBytes   = 4 * 1024 * 1024
340			maxSignalsEach = 400
341		)
342		caps := regressionScanCaps{MaxFiles: maxFiles, MaxSignals: maxSignalsEach}
343		// Resolve excluded transcript paths before reading any history. A broken
344		// manifest or privacy policy must fail closed, not disable exclusion.
345		manifest, err := bmanifest.Load(brainDir)
346		if err != nil {
347			return nil, nil, nil, caps, err
348		}
349		guard, err := loadSessionReadGuard(brainDir, manifest)
350		if err != nil {
351			return nil, nil, nil, caps, err
352		}
353		lowIDs := make([]string, 0, len(ids))
354		for _, id := range ids {
355			lowIDs = append(lowIDs, strings.ToLower(id))
356		}
357		var changes []changeSignal
358		var deletes []deleteSignal
359		files := map[string]struct{}{}
360		seenC := map[string]int{}
361		seenD := map[string]int{}
362		scanned := 0
363		_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
364			if err != nil {
365				return nil
366			}
367			if d.IsDir() {
368				if n := d.Name(); n == semstore.DirName || n == ".git" {
369					return filepath.SkipDir
370				}
371				return nil
372			}
373			// Record WHICH cap fired before abandoning the walk. Stopping silently here is what let
374			// "No suspected regressions" be printed over a scan that never finished.
375			if scanned >= maxFiles {
376				caps.FileCap = true
377			}
378			if len(seenC) >= maxSignalsEach && len(seenD) >= maxSignalsEach {
379				caps.SignalCap = true
380			}
381			if caps.FileCap || caps.SignalCap {
382				return filepath.SkipAll
383			}
384			switch filepath.Ext(path) {
385			case ".jsonl", ".json", ".md", ".txt":
386			default:
387				return nil
388			}
389			rel, _ := filepath.Rel(brainDir, path)
390			relSlash := filepath.ToSlash(rel)
391			if brainRawScanSkipsDerived(relSlash) {
392				return nil
393			}
394			if _, excluded := guard.Paths[relSlash]; excluded {
395				return nil
396			}
397			f, openErr := os.Open(path)
398			if openErr != nil {
399				return nil
400			}
401			scanned++
402			sc := bufio.NewScanner(f)
403			sc.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
404			lineNo := 0
405			for sc.Scan() {
406				lineNo++
407				line := sc.Text()
408				low := strings.ToLower(line)
409				matched := false
410				for _, id := range lowIDs {
411					if !strings.Contains(low, id) {
412						continue
413					}
414					matched = true
415					ex := normalizeHistoryTextForExcerpt(line)
416					ev := relSlash + ":" + strconv.Itoa(lineNo)
417					c, dl := regressionExtractSignals(id, ex, ev)
418					hints := regressionLineFileHints(line)
419					for _, s := range c {
420						s.hints = hints
421						k := s.id + "|" + s.operand
422						if idx, ok := seenC[k]; ok {
423							changes[idx].hints = mergeRegressionHints(changes[idx].hints, hints)
424						} else {
425							seenC[k] = len(changes)
426							changes = append(changes, s)
427						}
428					}
429					for _, s := range dl {
430						s.hints = hints
431						k := s.target + "|" + s.rhs
432						if idx, ok := seenD[k]; ok {
433							deletes[idx].hints = mergeRegressionHints(deletes[idx].hints, hints)
434							deletes[idx].anchors = mergeRegressionHints(deletes[idx].anchors, s.anchors)
435						} else {
436							seenD[k] = len(deletes)
437							deletes = append(deletes, s)
438						}
439					}
440				}
441				if matched {
442					for _, fn := range regressionLineFileHints(line) {
443						files[fn] = struct{}{}
444					}
445				}
446			}
447			_ = f.Close()
448			return nil
449		})
450		caps.Scanned = scanned
451		return changes, deletes, files, caps, nil
452	}
453	
454	// detectRegressionAnomaliesCapped is detectRegressionAnomalies plus the raw-history truncation
455	// report. The caps are also rendered into warnings, but a caller that writes a summary sentence
456	// needs the flag itself: a note printed under a clean-bill-of-health headline is not a correction.
457	func detectRegressionAnomaliesCapped(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int, includeDeletions bool) ([]regressionAnomaly, int, []string, regressionScanCaps) {
458		var warnings []string
459		var caps regressionScanCaps
460		ids := brainBriefRawHistoryQueries(query)
461		if len(ids) == 0 {
462			return []regressionAnomaly{}, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}, caps
463		}
464	
465		candidateFiles := map[string]struct{}{}
466		semanticRank := map[string]int{} // clean path -> best (lowest) semantic rank; lower = stronger locus
467		runtimeTraceRank := map[string]int{}
468		if semSource != nil {
469			traces, err := semanticRuntimeTraceFacts(brainDir, semSource, query, 32)
470			if err != nil {
471				warnings = append(warnings, "runtime trace facts unavailable for review ranking")
472			}
473			for rank, trace := range traces {
474				if trace.Score <= 1 {
475					continue
476				}
477				clean := regressionCleanRelPath(semanticFirstNonEmpty(trace.FilePath, trace.Path))
478				if clean == "" || clean == "." || strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
479					continue
480				}
481				candidateFiles[clean] = struct{}{}
482				if r, ok := runtimeTraceRank[clean]; !ok || rank < r {
483					runtimeTraceRank[clean] = rank
484				}
485			}
486		}
487		for _, rawID := range ids {
488			id := strings.ToLower(rawID)
489			if semSource != nil {
490				if syms, _, _, err := semstore.ContextFacts(brainDir, semSource, id, 8, 0); err == nil {
491					for rank, s := range syms {
492						if s.FilePath == "" {
493							continue
494						}
495						c := regressionCleanRelPath(s.FilePath)
496						candidateFiles[c] = struct{}{}
497						if r, ok := semanticRank[c]; !ok || rank < r {
498							semanticRank[c] = rank
499						}
500					}
501				}
502			}
503		}
504		// Targeted history scan: walk the raw sessions once, keeping only signal-bearing lines (so a
505		// rare invariant isn't lost behind thousands of plain identifier mentions, as a capped
506		// generic scan would). Also collects the code files those sessions name.
507		changes, deletes, namedFiles, scanCaps, scanErr := regressionScanHistoryCapped(brainDir, ids)
508		caps = scanCaps
509		if scanErr != nil {
510			return nil, 0, append(warnings, "history scan unavailable: "+scanErr.Error()), caps
511		}
512		// Surface the truncation BEFORE any of the early returns below: a capped scan that then finds
513		// no candidate files must still tell the reader it stopped looking.
514		if w := caps.Warning(); w != "" {
515			warnings = append(warnings, w)
516		}
517		for f := range namedFiles {
518			candidateFiles[f] = struct{}{}
519		}
520		if len(changes) == 0 && len(deletes) == 0 {
521			return []regressionAnomaly{}, 0, append(warnings, "history holds no precise code assertions for these identifiers"), caps
522		}
523	
524		// Load all candidate files once.
525		var files []candFile
526		for file := range candidateFiles {
527			clean := regressionCleanRelPath(file)
528			if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
529				continue
530			}
531			nativeClean := filepath.FromSlash(clean)
532			full := filepath.Join(repoRoot, nativeClean)
533			if err := base.RejectSymlinkPathComponents(repoRoot, nativeClean); err != nil {
534				continue // per-component symlink guard, matching the brain's other repo reads
535			}
536			info, err := os.Stat(full)
537			if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
538				continue
539			}
540			data, err := os.ReadFile(full)
541			if err != nil {
542				continue
543			}
544			lines := strings.Split(string(data), "\n")
545			norm := make([]string, len(lines))
546			for i, ln := range lines {
547				norm[i] = regressionDespace(ln)
548			}
549			rank, isSem := semanticRank[clean]
550			if !isSem {
551				rank = 1 << 30
552			}
553			traceRank, hasTrace := runtimeTraceRank[clean]
554			if !hasTrace {
555				traceRank = 1 << 30
556			}
557			files = append(files, candFile{clean: clean, lines: lines, norm: norm, semantic: isSem, rank: rank, runtimeTrace: hasTrace, traceRank: traceRank, isTest: regressionIsTestPath(clean)})
558		}
559		if len(files) == 0 {
560			return []regressionAnomaly{}, 0, append(warnings, "no current files to verify against (code index missing?)"), caps
561		}
562		// Deterministic, locus-prioritized order: implementation before tests, then by semantic rank
563		// (the strongest fix-site first), then path — so a finding lands on the actual fix site, not a
564		// random file that happens to share a common operand like `..HEAD`.
565		sort.SliceStable(files, func(i, j int) bool {
566			if files[i].isTest != files[j].isTest {
567				return !files[i].isTest
568			}
569			if files[i].runtimeTrace != files[j].runtimeTrace {
570				return files[i].runtimeTrace
571			}
572			if files[i].traceRank != files[j].traceRank {
573				return files[i].traceRank < files[j].traceRank
574			}
575			if files[i].rank != files[j].rank {
576				return files[i].rank < files[j].rank
577			}
578			return files[i].clean < files[j].clean
579		})
580	
581		// "invariant still holds" check — must use the SAME comment/test filter as the emit loop, or a
582		// stale comment/test copy of `operand+id` would falsely suppress a real regression (false negative).
583		fileLineBoth := func(f candFile, a, b string) bool {
584			if f.isTest {
585				return false
586			}
587			for i, n := range f.norm {
588				if regressionIsComment(f.lines[i]) {
589					continue
590				}
591				if strings.Contains(n, a) && strings.Contains(n, b) {
592					return true
593				}
594			}
595			return false
596		}
597		anyLineBoth := func(a, b string) bool {
598			for _, f := range files {
599				if fileLineBoth(f, a, b) {
600					return true
601				}
602			}
603			return false
604		}
605		anyHas := func(needle string) bool {
606			for _, f := range files {
607				for _, n := range f.norm {
608					if strings.Contains(n, needle) {
609						return true
610					}
611				}
612			}
613			return false
614		}
615	
616		var anomalies []regressionAnomaly
617	
618		for _, c := range dedupeChanges(changes) {
619			// Likely-rename guard: if the operand is still concatenated to SOME identifier
620			// (`<ident> + "...operand..."`, structure preserved), the invariant is intact under a renamed
621			// symbol, not regressed — only flag when the operand now sits in a bare/hardcoded literal.
622			renameRe := regexp.MustCompile(`[a-z_][a-z0-9_]*\s*\+\s*"[^"]*` + regexp.QuoteMeta(c.operand))
623			hinted := map[string]struct{}{}
624			for _, h := range c.hints {
625				hinted[regressionCleanRelPath(h)] = struct{}{}
626			}
627			if len(hinted) > 0 {
628				present := false
629				for _, f := range files {
630					if _, ok := hinted[f.clean]; ok {
631						present = true
632						break
633					}
634				}
635				if !present {
636					// Every hinted file is deleted or was skipped at load. Hints
637					// narrow the scan; they must not VETO it — dropping the
638					// candidate here would silently lose the strongest signal
639					// (history named exact loci) exactly when the code moved.
640					hinted = map[string]struct{}{}
641				}
642			}
643			if len(hinted) == 0 && anyLineBoth(c.operand, c.id) {
644				continue // invariant still holds somewhere, and history did not name per-file loci
645			}
646			found := false
647			for _, f := range files { // locate the swap: operand present, identifier gone
648				if len(hinted) > 0 {
649					if _, ok := hinted[f.clean]; !ok {
650						continue
651					}
652					if fileLineBoth(f, c.operand, c.id) {
653						continue // this hinted file still holds the invariant; do not let it mask peers
654					}
655				}
656				if f.isTest {
657					continue // a test's `..HEAD` is not the regressed implementation site
658				}
659				for i, n := range f.norm {
660					if regressionIsComment(f.lines[i]) {
661						continue // prose mentions of a range like `main...HEAD` are not the regression
662					}
663					if strings.Contains(n, c.operand) && !strings.Contains(n, c.id) {
664						if renameRe.MatchString(strings.ToLower(f.lines[i])) {
665							continue // operand still concatenated to an identifier → benign rename, not a regression
666						}
667						anomalies = append(anomalies, regressionAnomaly{
668							File: f.clean, Line: i + 1, Kind: "changed",
669							Current: strings.TrimSpace(f.lines[i]), Expected: c.raw,
670							Identifier: c.id, Confidence: 0.8, Evidence: c.ev,
671							Reason:    fmt.Sprintf("suspected regression: history asserts %q; this line keeps %q but dropped %q (could also be a rename — verify)", c.raw, c.operand, c.id),
672							rankBoost: regressionCandidateRankBoost(f),
673						})
674						found = true
675						break
676					}
677				}
678				if found && len(hinted) == 0 {
679					break
680				}
681			}
682		}
683	
684		for _, d := range dedupeDeletes(deletes) {
685			if !includeDeletions {
686				break // deletions are higher-recall but noisier (benign churn) — opt-in only
687			}
688			// The SPECIFIC assignment (target + its RHS) must be absent everywhere — a different
689			// assignment to the same field in another file is not this regression.
690			isCallDeletion := strings.HasSuffix(d.target, "(")
691			if isCallDeletion && len(d.anchors) > 0 {
692				homes := regressionMissingCallHomes(files, d)
693				if len(homes) > 0 {
694					for _, h := range homes {
695						anomalies = append(anomalies, regressionAnomaly{
696							File: h.file, Line: h.line, Kind: "deleted",
697							Current: h.current, Expected: d.raw,
698							Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
699							Reason:    fmt.Sprintf("history asserts `%s` near a peer state update, but that call is absent at this current locus", d.raw),
700							rankBoost: 3,
701						})
702					}
703					continue
704				}
705			}
706			if !isCallDeletion && len(d.hints) > 0 {
707				homes := regressionMissingAssignmentHomes(files, d)
708				if len(homes) > 0 {
709					for _, h := range homes {
710						anomalies = append(anomalies, regressionAnomaly{
711							File: h.file, Line: h.line, Kind: "deleted",
712							Current: h.current, Expected: d.raw,
713							Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
714							Reason:    fmt.Sprintf("history asserts `%s` in this hinted file, but that assignment is absent at this current locus", d.raw),
715							rankBoost: 1,
716						})
717					}
718					continue
719				}
720			}
721			if anyHas(d.target+d.rhs) || (!isCallDeletion && !anyHas(d.id)) {
722				continue
723			}
724			// Locate the home file: prefer one that also holds the RHS token (the natural site of
725			// the assignment), else the first file where the identifier appears.
726			home, line, cur := regressionHomeFile(files, d.id, d.rhs, d.hints)
727			if home == "" {
728				continue
729			}
730			invariantKind := "assignment"
731			if isCallDeletion {
732				invariantKind = "call"
733			}
734			rankBoost := 0
735			if len(d.hints) > 0 {
736				rankBoost = 1
737			}
738			if isCallDeletion {
739				rankBoost = 2
740				if len(d.hints) > 0 {
741					rankBoost = 3
742				}
743			}
744			anomalies = append(anomalies, regressionAnomaly{
745				File: home, Line: line, Kind: "deleted",
746				Current: cur, Expected: d.raw,
747				Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
748				Reason:    fmt.Sprintf("history asserts `%s` but that %s is absent everywhere in the current tree", d.raw, invariantKind),
749				rankBoost: rankBoost,
750			})
751		}
752	
753		anomalies = annotateRegressionLocationContext(regressionDedupeRank(anomalies), files)
754		if limit > 0 && len(anomalies) > limit {
755			anomalies = anomalies[:limit]
756		}
757		if len(anomalies) > regressionMaxAnomalies {
758			anomalies = anomalies[:regressionMaxAnomalies]
759		}
760		if anomalies == nil {
761			anomalies = []regressionAnomaly{}
762		}
763		return anomalies, len(files), warnings, caps
764	}
765	
766	type regressionHome struct {
767		file    string
768		line    int
769		current string
770	}
771	
772	func regressionMissingCallHomes(files []candFile, d deleteSignal) []regressionHome {
773		if !strings.HasSuffix(d.target, "(") || len(d.anchors) == 0 {
774			return nil
775		}
776		callNeedle := d.target + d.rhs
777		hinted := map[string]struct{}{}
778		for _, h := range d.hints {
779			hinted[regressionCleanRelPath(h)] = struct{}{}
780		}
781		scan := func(requireHint bool) []regressionHome {
782			var homes []regressionHome
783			seen := map[string]struct{}{}
784			for _, f := range files {
785				if requireHint {
786					if _, ok := hinted[f.clean]; !ok {
787						continue
788					}
789				}
