855	func regressionAssignmentCandidateHomes(f candFile, d deleteSignal) []regressionHome {
856		var homes []regressionHome
857		seenLine := map[int]struct{}{}
858		var preferredLines []int
859		var rhsLines []int
860		fileHasRHS := false
861		if d.rhs != "" {
862			for i, n := range f.norm {
863				if regressionIsComment(f.lines[i]) {
864					continue
865				}
866				if strings.Contains(n, d.rhs) {
867					fileHasRHS = true
868					break
869				}
870			}
871		}
872		collect := func(needle string) {
873			if needle == "" {
874				return
875			}
876			for i, n := range f.norm {
877				if !strings.Contains(n, needle) || regressionIsComment(f.lines[i]) {
878					continue
879				}
880				if len(regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(f.lines[i]))) == 2 {
881					continue
882				}
883				line := i + 1
884				if needle == d.id {
885					if fileHasRHS && !regressionSymbolHas(f, line, d.rhs) {
886						continue
887					}
888					if regressionNearbyCandidateSeenInSameSymbol(f.lines, preferredLines, line, 2) {
889						continue
890					}
891				}
892				if needle == d.rhs {
893					if regressionNearbyCandidateSeenInSameSymbol(f.lines, preferredLines, line, 2) ||
894						regressionNearbyCandidateSeenInSameSymbol(f.lines, rhsLines, line, 2) {
895						continue
896					}
897				}
898				if _, ok := seenLine[line]; ok {
899					continue
900				}
901				seenLine[line] = struct{}{}
902				if needle == d.id {
903					preferredLines = append(preferredLines, line)
904				}
905				if needle == d.rhs {
906					rhsLines = append(rhsLines, line)
907				}
908				homes = append(homes, regressionHome{file: f.clean, line: line, current: strings.TrimSpace(f.lines[i])})
909			}
910		}
911		collect(d.id)
912		collect(d.rhs)
913		return homes
914	}
