923	func regressionNearbyCandidateSeenInSameSymbol(src []string, lines []int, line, radius int) bool {
924		start, end, ok := regressionEnclosingSymbolRange(src, line)
925		for _, seen := range lines {
926			if seen < line-radius || seen > line+radius {
927				continue
928			}
929			seenStart, seenEnd, seenOK := regressionEnclosingSymbolRange(src, seen)
930			if ok != seenOK {
931				continue // one resolved to a symbol, the other did not: different scopes
932			}
933			if ok && (start != seenStart || end != seenEnd) {
934				continue // both resolved, but to different symbols
935			}
936			return true // same symbol, or neither resolved (radius proximity decides)
937		}
938		return false
939	}
