990	// regressionHomeFile returns the best (file, line, text) to attribute a deletion to: a file
991	// containing both the identifier and the RHS token, else the first file holding the identifier.
992	func regressionHomeFile(files []candFile, id, rhs string, hints []string) (string, int, string) {
993		findIDLine := func(f candFile, allowComment bool) (int, string, bool) {
994			for i, n := range f.norm {
995				if !strings.Contains(n, id) {
996					continue
997				}
998				if !allowComment && regressionIsComment(f.lines[i]) {
999					continue
1000				}
1001				return i + 1, strings.TrimSpace(f.lines[i]), true
1002			}
1003			return 0, "", false
1004		}
1005		findRHSLine := func(f candFile, allowComment bool) (int, string, bool) {
1006			if rhs == "" {
1007				return 0, "", false
1008			}
1009			for i, n := range f.norm {
1010				if !strings.Contains(n, rhs) || !strings.Contains(n, "=") {
1011					continue
1012				}
1013				if !allowComment && regressionIsComment(f.lines[i]) {
1014					continue
1015				}
1016				return i + 1, strings.TrimSpace(f.lines[i]), true
1017			}
1018			for i, n := range f.norm {
1019				if !strings.Contains(n, rhs) {
1020					continue
1021				}
1022				if !allowComment && regressionIsComment(f.lines[i]) {
1023					continue
1024				}
1025				return i + 1, strings.TrimSpace(f.lines[i]), true
1026			}
1027			return 0, "", false
1028		}
1029		if len(hints) > 0 {
1030			hinted := map[string]struct{}{}
1031			for _, h := range hints {
1032				hinted[regressionCleanRelPath(h)] = struct{}{}
1033			}
1034			for _, f := range files {
1035				if _, ok := hinted[f.clean]; !ok {
1036					continue
1037				}
1038				if line, cur, ok := findIDLine(f, false); ok {
1039					return f.clean, line, cur
1040				}
1041				if line, cur, ok := findRHSLine(f, false); ok {
1042					return f.clean, line, cur
1043				}
1044			}
1045			for _, f := range files {
1046				if _, ok := hinted[f.clean]; !ok {
1047					continue
1048				}
1049				if line, cur, ok := findIDLine(f, true); ok {
1050					return f.clean, line, cur
1051				}
1052				if line, cur, ok := findRHSLine(f, true); ok {
1053					return f.clean, line, cur
1054				}
1055			}
1056		}
1057		if rhs != "" {
1058			for _, f := range files {
1059				if !fileHasNorm(f.norm, rhs) {
1060					continue
1061				}
1062				if line, cur, ok := findIDLine(f, false); ok {
1063					return f.clean, line, cur
1064				}
1065			}
1066			for _, f := range files {
1067				if !fileHasNorm(f.norm, rhs) {
1068					continue
1069				}
1070				if line, cur, ok := findIDLine(f, true); ok {
1071					return f.clean, line, cur
1072				}
1073			}
1074		}
1075		for _, f := range files {
1076			if line, cur, ok := findIDLine(f, false); ok {
1077				return f.clean, line, cur
1078			}
1079		}
1080		for _, f := range files {
1081			if line, cur, ok := findIDLine(f, true); ok {
1082				return f.clean, line, cur
1083			}
1084		}
1085		return "", 0, "(absent)"
1086	}
