1161	// regressionFunctionPattern recognizes the common declaration heads across
1162	// the languages regressionCodeFilePattern admits: Go func (with optional
1163	// receiver), Python def, Rust fn, JS/TS function (incl. export/async), and
1164	// class declarations. Best-effort by design — a miss only widens symbol
1165	// grouping back to line-radius proximity, it never drops a finding.
1166	var regressionFunctionPattern = regexp.MustCompile(`^\s*(?:func\s+(?:\([^)]+\)\s*)?|def\s+|fn\s+|(?:export\s+)?(?:default\s+)?(?:async\s+)?function\s*\*?\s*|class\s+)([A-Za-z_][A-Za-z0-9_]*)`)
1167	
1168	func regressionEnclosingSymbol(lines []string, line int) string {
1169		start, _, ok := regressionEnclosingSymbolRange(lines, line)
1170		if !ok {
1171			return ""
1172		}
1173		match := regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[start]))
1174		if len(match) == 2 {
1175			return match[1]
1176		}
1177		return ""
1178	}
1179	
1180	func regressionEnclosingSymbolRange(lines []string, line int) (int, int, bool) {
1181		if line <= 0 || line > len(lines) {
1182			return 0, 0, false
1183		}
1184		start := line - 1
1185		for i := start; i >= 0 && i >= start-250; i-- {
1186			match := regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[i]))
1187			if len(match) == 2 {
1188				end := len(lines)
1189				for j := i + 1; j < len(lines); j++ {
1190					if len(regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[j]))) == 2 {
1191						end = j
1192						break
1193					}
1194				}
1195				return i, end, true
1196			}
1197		}
1198		return 0, 0, false
1199	}
