1201	func annotateRegressionLocationContext(anomalies []regressionAnomaly, files []candFile) []regressionAnomaly {
1202		if len(anomalies) == 0 {
1203			return anomalies
1204		}
1205		byFile := map[string]candFile{}
1206		for _, f := range files {
1207			byFile[f.clean] = f
1208		}
1209		for i := range anomalies {
1210			if anomalies[i].Symbol != "" {
1211				continue
1212			}
1213			if f, ok := byFile[regressionCleanRelPath(anomalies[i].File)]; ok {
1214				anomalies[i].Symbol = regressionEnclosingSymbol(f.lines, anomalies[i].Line)
1215			}
1216		}
1217		for i := range anomalies {
1218			var related []string
1219			for j := range anomalies {
1220				if i == j || anomalies[i].File != anomalies[j].File || anomalies[i].Kind != anomalies[j].Kind || anomalies[j].Line <= 0 {
1221					continue
1222				}
1223				if !regressionRelatedLocationMatch(anomalies[i], anomalies[j]) {
1224					continue
1225				}
1226				loc := fmt.Sprintf("%s:%d", anomalies[j].File, anomalies[j].Line)
1227				if anomalies[j].Symbol != "" {
1228					loc += " (" + anomalies[j].Symbol + ")"
1229				}
1230				related = append(related, loc)
1231				if len(related) >= 6 {
1232					break
1233				}
1234			}
1235			anomalies[i].RelatedLocations = related
1236		}
1237		return anomalies
1238	}
