1240	func regressionRelatedLocationMatch(a, b regressionAnomaly) bool {
1241		aExpected := regressionDespace(a.Expected)
1242		bExpected := regressionDespace(b.Expected)
1243		if aExpected != "" || bExpected != "" {
1244			return aExpected != "" && aExpected == bExpected
1245		}
1246		return a.Identifier != "" && b.Identifier != "" && strings.EqualFold(a.Identifier, b.Identifier)
1247	}
