1249	func runRegressionDetect(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
1250		if ro.limit <= 0 {
1251			ro.limit = 20
1252		}
1253		target := agentSurfaceTarget(opts, nil)
1254		status, err := buildBrainStatusReport(ctx, opts, target)
1255		if err != nil {
1256			return err
1257		}
1258		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(status.Brain.Path)
1259		if err != nil {
1260			return err
1261		}
1262		var semSource *semanticSourceManifest
1263		if status.Manifest != nil && status.Manifest.Sources != nil {
1264			semSource = status.Manifest.Sources.Semantic
1265		}
1266		anomalies, scanned, warnings, caps := detectRegressionAnomaliesCapped(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
1267		if ro.locationOnly {
1268			// Hand only the suspected location, not the fix — so a fair A/B measures detection, not
1269			// the agent pasting a harness-computed `expected`.
1270			for i := range anomalies {
1271				anomalies[i].Expected = ""
1272				anomalies[i].Current = ""
1273				anomalies[i].Reason = "suspected regression site (location only)"
1274				if anomalies[i].Symbol != "" || len(anomalies[i].RelatedLocations) > 0 {
1275					anomalies[i].Reason = "suspected regression site (location only); inspect the enclosing symbol and related same-file locations"
1276				}
1277			}
1278		}
1279		report := regressionReport{
1280			SchemaVersion:    reviewReportSchemaVersion,
1281			GeneratedAt:      opts.Now().UTC(),
1282			Query:            query,
1283			RepoPath:         status.Repo.Root,
1284			BrainPath:        status.Brain.Path,
1285			Anomalies:        anomalies,
1286			Scanned:          scanned,
1287			HistoryTruncated: caps.Truncated(),
1288			Warnings:         warnings,
1289		}
1290		render := func() error {
1291			if ro.json {
1292				return cmdutil.WriteJSON(cmd, report)
1293			}
1294			out := cmd.OutOrStdout()
1295			if len(anomalies) == 0 {
1296				fmt.Fprintln(out, regressionNoAnomaliesLine(query, scanned, caps.Truncated()))
1297				for _, w := range warnings {
1298					fmt.Fprintf(out, "  note: %s\n", w)
1299				}
1300				return nil
1301			}
1302			fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
1303			for _, a := range anomalies {
1304				fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
1305					a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
1306			}
1307			return nil
1308		}
1309		return bufferRetrievalCommandOutput(cmd, []retrievalPrivacyPolicy{privacyPolicy}, render)
1310	}
