1401	// regressionSeverity maps detector confidence to a review severity. Every finding the current
1402	// heuristic detector emits is *suspected* — `changed` (0.8) is precise but rename-ambiguous and
1403	// `deleted` (0.65) is noisier/opt-in — so none warrant "high". That tier is reserved for a future
1404	// high-confidence signal (a durable fact bound to a locus with recency), so the machine severity
1405	// never contradicts the "could be a rename — verify" hedge: changed -> medium, deleted -> low.
1406	func regressionSeverity(conf float64) string {
1407		switch {
1408		case conf >= 0.9:
1409			return "high" // reserved: no heuristic finding reaches this today
1410		case conf >= 0.7:
1411			return "medium"
1412		default:
1413			return "low"
1414		}
1415	}
1416	
1417	// regressionNoAnomaliesLine is the headline `inspect regressions` prints when nothing was
1418	// flagged. Like reviewSummary, it may never claim more than the run established.
1419	//
1420	// There are three distinct causes of zero findings and they used to share two sentences:
1421	//   - scanned == 0: nothing was compared at all.
1422	//   - the raw-history walk hit a file or signal cap and abandoned the rest of the brain: the
1423	//     comparison that did run was over a PREFIX of history. "No suspected regressions" read as a
1424	//     clean bill of health for evidence that was never opened.
1425	//   - the scan completed: the only case that earns the unqualified sentence.
1426	func regressionNoAnomaliesLine(query string, scanned int, historyTruncated bool) string {
1427		switch {
1428		case scanned == 0:
1429			return fmt.Sprintf("INCONCLUSIVE for %q: nothing was compared (0 files scanned).", query)
1430		case historyTruncated:
1431			return fmt.Sprintf("PARTIAL for %q: nothing flagged in what was compared (scanned %d files), but the history scan stopped at a cap before the end of the brain, so this is not a clean bill of health (see the notes below).", query, scanned)
1432		default:
1433			return fmt.Sprintf("No suspected regressions for %q (scanned %d files).", query, scanned)
1434		}
1435	}
1436	
1437	// reviewSummary is the one line a reader takes away, and it may never say more
1438	// than the run actually established.
1439	//
1440	// Zero findings has two completely different causes and they were reported with
1441	// the same sentence: "no suspected regressions (current tree matches the brain's
1442	// memory)". On a brain that was never built, or whose history holds no precise
1443	// code assertions for the query, detectRegressionAnomalies returns before it
1444	// opens a single file — scanned == 0 — and that sentence became a clean bill of
1445	// health for a comparison that never happened. The contradiction was printed
1446	// directly underneath it, as "note: history holds no precise code assertions for
1447	// these identifiers", but the summary is the line people quote.
1448	//
1449	// scanned is the number of current files actually read and compared, so
1450	// scanned == 0 is the precise, non-string-matched test for "nothing was
1451	// checked".
1452	func reviewSummary(findings, scanned int, historyTruncated bool) string {
1453		switch {
1454		case historyTruncated && scanned > 0:
1455			return fmt.Sprintf("Diff-less review: PARTIAL — %d suspected regression(s) in %d file(s) compared; the history scan stopped at a cap, so this is not a clean result and additional regressions may exist. See the notes below.", findings, scanned)
1456		case findings > 0:
1457			return fmt.Sprintf("Diff-less review: %d suspected regression(s) — verify each before acting.", findings)
1458		case scanned == 0:
1459			return "Diff-less review: INCONCLUSIVE — nothing was compared (the brain holds no code assertions to check this tree against). This is not a clean result; see the notes below."
1460		default:
1461			return fmt.Sprintf("Diff-less review: no suspected regressions (%d file(s) compared against the brain's memory).", scanned)
1462		}
1463	}
