1465	func anomalyToReviewFinding(a regressionAnomaly) reviewFinding {
1466		detail := "suspected regression at this location — verify against the brain's history."
1467		if a.Expected != "" {
1468			detail = fmt.Sprintf("history shows `%s`; current is `%s` — verify this change is intentional (could also be a rename).", a.Expected, a.Current)
1469		}
1470		return reviewFinding{
1471			Severity:   regressionSeverity(a.Confidence),
1472			File:       a.File,
1473			Line:       a.Line,
1474			Title:      fmt.Sprintf("Suspected regression: `%s` %s", a.Identifier, a.Kind),
1475			Detail:     detail,
1476			Evidence:   a.Evidence,
1477			Confidence: a.Confidence,
1478		}
1479	}
