1481	func runBrainReview(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
1482		if ro.limit <= 0 {
1483			ro.limit = 20
1484		}
1485		target := agentSurfaceTarget(opts, nil)
1486		status, err := buildBrainStatusReport(ctx, opts, target)
1487		if err != nil {
1488			return err
1489		}
1490		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(status.Brain.Path)
1491		if err != nil {
1492			return err
1493		}
1494		if ro.patterns {
1495			privacyPolicy.RequireDerivedClean = true
1496			if err := requirePrivacyDerivedRead(status.Brain.Path); err != nil {
1497				return err
1498			}
1499			if err := requirePatternCorpusAvailable(status.Brain.Path); err != nil {
1500				return err
1501			}
1502		}
1503		var semSource *semanticSourceManifest
1504		if status.Manifest != nil && status.Manifest.Sources != nil {
1505			semSource = status.Manifest.Sources.Semantic
1506		}
1507		anomalies, scanned, warnings, caps := detectRegressionAnomaliesCapped(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
1508		var runtimeTraces []semanticRecord
1509		if semSource != nil {
1510			traces, err := semanticRuntimeTraceFacts(status.Brain.Path, semSource, query, ro.limit)
1511			if err != nil {
1512				warnings = append(warnings, "runtime trace facts unavailable for review context")
1513			} else {
1514				for _, trace := range traces {
1515					if trace.Score > 1 {
1516						runtimeTraces = append(runtimeTraces, trace)
1517					}
1518				}
1519			}
1520		}
1521		if ro.locationOnly {
1522			// Parity with `inspect regressions --location-only`: hand the suspected site, not the fix,
1523			// so a fair consumer/A-B measures detection rather than pasting a harness-computed value.
1524			for i := range anomalies {
1525				anomalies[i].Expected = ""
1526				anomalies[i].Current = ""
1527				anomalies[i].Reason = "suspected regression site (location only)"
1528			}
1529		}
1530		findings := make([]reviewFinding, 0, len(anomalies))
1531		for _, a := range anomalies {
1532			findings = append(findings, anomalyToReviewFinding(a))
1533		}
1534		report := reviewReport{
1535			SchemaVersion: reviewReportSchemaVersion,
1536			GeneratedAt:   opts.Now().UTC(),
1537			Mode:          "diff-less (brain memory vs current tree)",
1538			Query:         query,
1539			RepoPath:      status.Repo.Root,
1540			BrainPath:     status.Brain.Path,
1541			Summary:       reviewSummary(len(findings), scanned, caps.Truncated()),
1542			Checked:       scanned > 0,
1543			FilesScanned:  scanned,
1544			Findings:      findings,
1545			Warnings:      warnings,
1546			RuntimeTraces: runtimeTraces,
1547		}
1548		if ro.patterns {
1549			files := make([]string, 0, len(findings))
1550			for _, f := range findings {
1551				files = append(files, f.File)
1552			}
1553			report.PatternContext, err = loadReviewPatternContextChecked(status.Brain.Path, files, ro.limit)
1554			if err != nil {
1555				return err
1556			}
1557		}
1558		render := func() error {
1559			if ro.json {
1560				return cmdutil.WriteJSON(cmd, report)
1561			}
1562			out := cmd.OutOrStdout()
1563			fmt.Fprintln(out, report.Summary)
1564			for _, f := range findings {
1565				fmt.Fprintf(out, "\n  [%s] %s\n    %s:%d\n    %s\n    evidence: %s\n",
1566					strings.ToUpper(f.Severity), f.Title, f.File, f.Line, f.Detail, f.Evidence)
1567			}
1568			for _, pc := range report.PatternContext {
1569				fmt.Fprintf(out, "  pattern context [%s] %s — %s   id %s\n", pc.Type, pc.File, pc.Title, pc.ID)
1570			}
1571			for _, w := range warnings {
1572				fmt.Fprintf(out, "  note: %s\n", w)
1573			}
1574			return nil
1575		}
1576		return bufferRetrievalCommandOutput(cmd, []retrievalPrivacyPolicy{privacyPolicy}, render)
1577	}
