10	// The uncapped detectRegressionAnomalies wrapper discarded regressionScanCaps,
11	// so every caller except runRegressionDetect lost the "history scan stopped
12	// early" signal. `brain review` and the workspace regressions/review surfaces
13	// could then print an unqualified clean bill of health over a raw-history scan
14	// that hit a cap and never finished -- the exact bug class the caps were added
15	// to eliminate, simply not propagated.
16	//
17	// regressionNoAnomaliesLine had said this correctly since the caps existed.
18	// These two summaries could not, because they never received the flag.
19	func TestReviewSummaryQualifiesATruncatedScan(t *testing.T) {
20		t.Parallel()
21	
22		clean := reviewSummary(0, 7, false)
23		if !strings.Contains(clean, "no suspected regressions") {
24			t.Fatalf("an untruncated clean scan must still read clean: %q", clean)
25		}
26		partial := reviewSummary(0, 7, true)
27		if strings.Contains(partial, "no suspected regressions") {
28			t.Errorf("a truncated scan must not read as a clean bill of health: %q", partial)
29		}
30		for _, want := range []string{"PARTIAL", "stopped at a cap", "not a clean result"} {
31			if !strings.Contains(partial, want) {
32				t.Errorf("the partial summary must contain %q: %q", want, partial)
33			}
34		}
35		// Findings outrank the qualifier: there is nothing clean to qualify.
36		if got := reviewSummary(2, 7, true); !strings.Contains(got, "suspected regression(s)") {
37			t.Errorf("findings must still be reported first: %q", got)
38		}
39		// Nothing compared stays INCONCLUSIVE, which is stronger than PARTIAL.
40		if got := reviewSummary(0, 0, true); !strings.Contains(got, "INCONCLUSIVE") {
41			t.Errorf("a scan that compared nothing is inconclusive, not partial: %q", got)
42		}
43	}
