45	func TestWorkspaceReviewSummaryQualifiesATruncatedScan(t *testing.T) {
46		t.Parallel()
47	
48		clean := workspaceReviewSummary(true, 3, false)
49		if !strings.Contains(clean, "no suspected regressions") {
50			t.Fatalf("an untruncated clean scan must still read clean: %q", clean)
51		}
52		partial := workspaceReviewSummary(true, 3, true)
53		if strings.Contains(partial, "no suspected regressions") {
54			t.Errorf("a truncated scan must not read as a clean bill of health: %q", partial)
55		}
56		for _, want := range []string{"PARTIAL", "stopped at a cap"} {
57			if !strings.Contains(partial, want) {
58				t.Errorf("the partial summary must contain %q: %q", want, partial)
59			}
60		}
61		// Nothing compared stays INCONCLUSIVE even when truncated.
62		if got := workspaceReviewSummary(true, 0, true); !strings.Contains(got, "INCONCLUSIVE") {
63			t.Errorf("a scan that compared nothing is inconclusive: %q", got)
64		}
65	}
