67	// NON-VACUITY / structural: the uncapped wrapper is gone, so no future caller
68	// can silently discard the caps again. A test asserting the summaries handle a
69	// flag means nothing if the production path never passes a true one.
70	func TestNoUncappedRegressionDetectorRemains(t *testing.T) {
71		t.Parallel()
72	
73		for _, file := range []string{"regression.go", "workspace.go"} {
74			src := readGoSourceForTest(t, file)
75			// The capped detector must be what production calls.
76			if !strings.Contains(src, "detectRegressionAnomaliesCapped(") {
77				t.Errorf("%s does not call the capped detector", file)
78			}
79			// And the uncapped wrapper must not exist to be called.
80			if strings.Contains(src, "func detectRegressionAnomalies(") {
81				t.Errorf("%s still defines the uncapped wrapper, which is how the caps got discarded", file)
82			}
83		}
84		// Both summaries must receive a real flag, not a literal false.
85		src := readGoSourceForTest(t, "regression.go")
86		if !strings.Contains(src, "reviewSummary(len(findings), scanned, caps.Truncated())") {
87			t.Error("brain review does not pass the truncation flag into its summary")
88		}
89		ws := readGoSourceForTest(t, "workspace.go")
90		if !strings.Contains(ws, "workspaceReviewSummary(result.Checked, result.FilesScanned, result.HistoryTruncated)") {
91			t.Error("workspace review does not pass the truncation flag into its summary")
92		}
93		if !strings.Contains(ws, "result.HistoryTruncated = truncated") {
94			t.Error("the workspace results never record the truncation flag, so the summary always sees false")
95		}
96	}
