98	// readGoSourceForTest reads a file in this package for a structural assertion,
99	// failing loudly when the file is missing or empty so the guard cannot pass
100	// vacuously.
101	func readGoSourceForTest(t *testing.T, name string) string {
102		t.Helper()
103		data, err := os.ReadFile(name)
104		if err != nil {
105			t.Fatalf("read %s: %v", name, err)
106		}
107		if len(data) == 0 {
108			t.Fatalf("%s is empty; this guard would be vacuous", name)
109		}
110		return string(data)
111	}
