113	// Measuring the input in runes and the ellipsis in BYTES is the same
114	// rune-versus-byte confusion truncateStatusCause exists to fix, on the other
115	// operand. It agrees for ASCII "..." and over-reserves the moment the marker
116	// becomes "…" -- one const edit away, in a function whose whole comment is
117	// about this class of bug.
118	//
119	// Driven by temporarily treating a multi-byte marker the way the code would:
120	// the assertion is that the reserve is a RUNE count, so a 1-rune 3-byte marker
121	// reserves 1, not 3.
122	func TestCauseTruncationReservesTheEllipsisInRunes(t *testing.T) {
123		t.Parallel()
124	
125		// A cause longer than the width must come back exactly statusCauseWidth
126		// runes: limit + ellipsis, with the ellipsis charged at its rune width.
127		long := strings.Repeat("a", statusCauseWidth*2)
128		got := truncateStatusCause(long)
129		if n := len([]rune(got)); n != statusCauseWidth {
130			t.Errorf("truncated cause is %d runes, want exactly %d (the advertised width)", n, statusCauseWidth)
131		}
132		if !strings.HasSuffix(got, statusCauseEllipsis) {
133			t.Errorf("a truncated cause must carry the marker: %q", got)
134		}
135	
136		// Non-ASCII input is charged per RUNE, not per byte -- the original bug.
137		wide := strings.Repeat("é", statusCauseWidth*2)
138		if n := len([]rune(truncateStatusCause(wide))); n != statusCauseWidth {
139			t.Errorf("multi-byte cause truncated to %d runes, want %d", n, statusCauseWidth)
140		}
141	
142		// And a cause that fits is returned untouched, so the reserve is not
143		// applied where it does not belong.
144		short := strings.Repeat("é", 3)
145		if got := truncateStatusCause(short); got != short {
146			t.Errorf("a cause that fits must be unchanged: %q != %q", got, short)
147		}
148	
149		// The structural half: the reserve must be a rune count in the source, or
150		// the assertions above pass today and break on the first "…".
151		src := readGoSourceForTest(t, "status_render.go")
152		if strings.Contains(src, "statusCauseWidth - len(statusCauseEllipsis)") {
153			t.Error("the ellipsis reserve is still a byte count, so a multi-byte marker would over-reserve")
154		}
155		if !strings.Contains(src, "utf8.RuneCountInString(statusCauseEllipsis)") {
156			t.Error("the ellipsis reserve is no longer counted in runes")
157		}
158	}
