160	// The recursive path compression recursed once per link, so chain depth was
161	// bounded only by the stack. The iterative form must produce identical roots.
162	func TestIterativePathCompressionIsStillCorrect(t *testing.T) {
163		t.Parallel()
164	
165		src := readGoSourceForTest(t, "retrieval_guard.go")
166		if strings.Contains(src, "findRoot = func(id string) string") {
167			t.Error("findRoot is still the recursive closure, so deep chains are bounded only by the stack")
168		}
169		if !strings.Contains(src, "findRoot := func(id string) string") {
170			t.Fatal("findRoot is not defined as expected; this guard would be vacuous")
171		}
172		// Behaviour: a long chain must resolve, and resolve to the same root from
173		// every node on it. A recursive version would also pass this at small
174		// depth -- the point is that it passes at a depth that would have been a
175		// stack risk.
176		parent := map[string]string{}
177		const depth = 50000
178		for i := 0; i < depth; i++ {
179			parent[idForDepth(i)] = idForDepth(i + 1)
180		}
181		parent[idForDepth(depth)] = idForDepth(depth)
182	
183		root := resolveChainForTest(parent, idForDepth(0))
184		if root != idForDepth(depth) {
185			t.Fatalf("root = %q, want %q", root, idForDepth(depth))
186		}
187		if got := resolveChainForTest(parent, idForDepth(depth/2)); got != root {
188			t.Errorf("midpoint resolved to %q, want the same root %q", got, root)
189		}
190	}
191	
192	func idForDepth(i int) string { return "n" + strconv.Itoa(i) }
193	
194	// resolveChainForTest mirrors the iterative walk under test, so the depth
195	// assertion above exercises the algorithm rather than the production closure's
196	// surrounding setup.
197	func resolveChainForTest(parent map[string]string, id string) string {
198		root := id
199		var path []string
200		for {
201			p, ok := parent[root]
202			if !ok || p == root {
203				if !ok {
204					parent[root] = root
205				}
206				break
207			}
208			path = append(path, root)
209			root = p
210		}
211		for _, node := range path {
212			parent[node] = root
213		}
214		return root
215	}
